// The program proves the file access of the package os against real Go inside
// a temporary directory: each open flag, a read at an offset, a seek with each
// whence, the fields of a Stat except the time, the directory operations, and
// the text of each error. It prints a relative name only, and no time.
package main

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"sort"
	"strings"
)

func row(label string, value any) {
	fmt.Printf("%-32s %v\n", label, value)
}

func files() {
	f, err := os.Create("a.txt")
	row("Create", err)
	row("Name", f.Name())
	n, err := f.WriteString("hello, world\n")
	row("WriteString", fmt.Sprint(n, " ", err))
	n, err = f.Write([]byte("second line\n"))
	row("Write", fmt.Sprint(n, " ", err))
	n, err = fmt.Fprintf(f, "%d-%s\n", 3, "third")
	row("Fprintf", fmt.Sprint(n, " ", err))
	info, err := f.Stat()
	row("File.Stat", fmt.Sprintf("%v name=%s size=%d dir=%v mode=%v", err, info.Name(), info.Size(), info.IsDir(), info.Mode()))
	row("Close", f.Close())
	row("Close twice", f.Close())
	_, err = f.Write([]byte("x"))
	row("Write after Close", err)
	row("is ErrClosed", errors.Is(err, os.ErrClosed))
	data, err := os.ReadFile("a.txt")
	row("ReadFile", fmt.Sprintf("%q %v", data, err))
	err = os.WriteFile("b.txt", []byte("written whole"), 0o644)
	row("WriteFile", err)
	data, err = os.ReadFile("b.txt")
	row("ReadFile b", fmt.Sprintf("%q %v", data, err))
	err = os.WriteFile("b.txt", []byte("replaced"), 0o644)
	data, _ = os.ReadFile("b.txt")
	row("WriteFile replaces", fmt.Sprintf("%q %v", data, err))
	_, err = os.ReadFile("missing.txt")
	row("ReadFile missing", err)
	row("is ErrNotExist", errors.Is(err, fs.ErrNotExist))
	row("IsNotExist", os.IsNotExist(err))
	var pe *fs.PathError
	row("as PathError", fmt.Sprintf("%v op=%q path=%q err=%v", errors.As(err, &pe), pe.Op, pe.Path, pe.Err))
	row("PathError Unwrap", errors.Unwrap(err) == pe.Err)
	row("Timeout", pe.Timeout())
	_, err = os.Open("missing.txt")
	row("Open missing", err)
	_, err = os.Stat("missing.txt")
	row("Stat missing", err)
	row("Stat missing IsNotExist", os.IsNotExist(err))
	_, err = os.ReadFile("nodir/missing.txt")
	row("ReadFile missing dir", err)
	f, err = os.Open("a.txt")
	row("Open", err)
	buf := make([]byte, 5)
	n, err = f.Read(buf)
	row("Read", fmt.Sprintf("%d %v %q", n, err, buf[:n]))
	n, err = f.ReadAt(buf, 7)
	row("ReadAt 7", fmt.Sprintf("%d %v %q", n, err, buf[:n]))
	pos, err := f.Seek(0, io.SeekCurrent)
	row("Seek current after ReadAt", fmt.Sprint(pos, " ", err))
	n, err = f.ReadAt(buf, 34)
	row("ReadAt near the end", fmt.Sprintf("%d %v %q", n, err, buf[:n]))
	n, err = f.ReadAt(buf, 100)
	row("ReadAt past the end", fmt.Sprintf("%d %v", n, err))
	n, err = f.ReadAt(buf, -1)
	row("ReadAt -1", fmt.Sprintf("%d %v", n, err))
	pos, err = f.Seek(2, io.SeekStart)
	row("Seek start", fmt.Sprint(pos, " ", err))
	n, _ = f.Read(buf)
	row("Read after Seek", fmt.Sprintf("%q", buf[:n]))
	pos, err = f.Seek(3, io.SeekCurrent)
	row("Seek current", fmt.Sprint(pos, " ", err))
	n, _ = f.Read(buf)
	row("Read after Seek current", fmt.Sprintf("%q", buf[:n]))
	pos, err = f.Seek(-6, io.SeekEnd)
	row("Seek end", fmt.Sprint(pos, " ", err))
	rest, err := io.ReadAll(f)
	row("ReadAll after Seek end", fmt.Sprintf("%q %v", rest, err))
	n, err = f.Read(buf)
	row("Read at end", fmt.Sprintf("%d %v", n, err))
	pos, err = f.Seek(10, io.SeekEnd)
	row("Seek past the end", fmt.Sprint(pos, " ", err))
	n, err = f.Read(buf)
	row("Read past the end", fmt.Sprintf("%d %v", n, err))
	_, err = f.Seek(-1, io.SeekStart)
	row("Seek negative", err)
	_, err = f.Write([]byte("x"))
	row("Write to a read only file", err)
	row("Close", f.Close())
	_, err = f.Read(buf)
	row("Read after Close", err)
	_, err = f.Seek(0, io.SeekStart)
	row("Seek after Close", err)
	_, err = f.Stat()
	row("Stat after Close", err)
}

func flags() {
	f, err := os.OpenFile("flag.txt", os.O_WRONLY|os.O_CREATE, 0o644)
	row("O_WRONLY|O_CREATE new", err)
	f.WriteString("0123456789")
	f.Close()
	f, err = os.OpenFile("flag.txt", os.O_WRONLY, 0o644)
	row("O_WRONLY existing", err)
	f.WriteString("ab")
	f.Close()
	data, _ := os.ReadFile("flag.txt")
	row("after O_WRONLY", fmt.Sprintf("%q", data))
	f, err = os.OpenFile("flag.txt", os.O_WRONLY|os.O_APPEND, 0o644)
	row("O_APPEND", err)
	f.WriteString("XY")
	f.Close()
	data, _ = os.ReadFile("flag.txt")
	row("after O_APPEND", fmt.Sprintf("%q", data))
	f, err = os.OpenFile("flag.txt", os.O_WRONLY|os.O_TRUNC, 0o644)
	row("O_TRUNC", err)
	f.WriteString("new")
	f.Close()
	data, _ = os.ReadFile("flag.txt")
	row("after O_TRUNC", fmt.Sprintf("%q", data))
	f, err = os.OpenFile("flag.txt", os.O_RDWR, 0o644)
	row("O_RDWR", err)
	buf := make([]byte, 3)
	n, err := f.Read(buf)
	row("O_RDWR Read", fmt.Sprintf("%d %v %q", n, err, buf[:n]))
	n, err = f.WriteAt([]byte("Z"), 1)
	row("O_RDWR WriteAt", fmt.Sprint(n, " ", err))
	f.Seek(0, io.SeekStart)
	n, _ = f.Read(buf)
	row("O_RDWR Read again", fmt.Sprintf("%q", buf[:n]))
	f.Close()
	f, err = os.OpenFile("flag.txt", os.O_RDONLY, 0o644)
	row("O_RDONLY", err)
	_, err = f.Write([]byte("x"))
	row("O_RDONLY Write", err)
	f.Close()
	_, err = os.OpenFile("flag.txt", os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	row("O_EXCL existing", err)
	row("is ErrExist", errors.Is(err, fs.ErrExist))
	row("IsExist", os.IsExist(err))
	f, err = os.OpenFile("excl.txt", os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	row("O_EXCL new", err)
	f.Close()
	_, err = os.OpenFile("missing.txt", os.O_WRONLY, 0o644)
	row("O_WRONLY missing", err)
	_, err = os.OpenFile("missing.txt", os.O_RDWR, 0o644)
	row("O_RDWR missing", err)
	_, err = os.OpenFile("missing.txt", os.O_RDONLY, 0o644)
	row("O_RDONLY missing", err)
	_, err = os.Stat("missing.txt")
	row("missing stays missing", os.IsNotExist(err))
	f, err = os.OpenFile("rdwr-create.txt", os.O_RDWR|os.O_CREATE, 0o644)
	row("O_RDWR|O_CREATE", err)
	f.WriteString("abc")
	f.Seek(0, io.SeekStart)
	data, _ = io.ReadAll(f)
	row("O_RDWR|O_CREATE read back", fmt.Sprintf("%q", data))
	f.Close()
	f, err = os.OpenFile("rdwr-create.txt", os.O_RDWR|os.O_CREATE, 0o644)
	data, _ = io.ReadAll(f)
	row("O_RDWR|O_CREATE keeps", fmt.Sprintf("%q %v", data, err))
	f.Close()
	f, _ = os.OpenFile("trunc-create.txt", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	f.WriteString("first")
	f.Close()
	f, _ = os.OpenFile("trunc-create.txt", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	f.WriteString("2nd")
	f.Close()
	data, _ = os.ReadFile("trunc-create.txt")
	row("O_TRUNC|O_CREATE", fmt.Sprintf("%q", data))
	f, _ = os.OpenFile("append-create.txt", os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	f.WriteString("one;")
	f.Close()
	f, _ = os.OpenFile("append-create.txt", os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	f.WriteString("two;")
	f.Close()
	data, _ = os.ReadFile("append-create.txt")
	row("O_APPEND|O_CREATE", fmt.Sprintf("%q", data))
	row("O_RDONLY value", os.O_RDONLY)
	row("O_WRONLY value", os.O_WRONLY)
	row("O_RDWR value", os.O_RDWR)
}

func stats() {
	os.WriteFile("size.bin", make([]byte, 1000), 0o644)
	info, err := os.Stat("size.bin")
	row("Stat", err)
	row("Name", info.Name())
	row("Size", info.Size())
	row("IsDir", info.IsDir())
	row("Mode", info.Mode())
	row("Mode IsRegular", info.Mode().IsRegular())
	row("Mode Perm", info.Mode().Perm())
	row("Mode Type", info.Mode().Type())
	row("ModTime is set", !info.ModTime().IsZero())
	err = os.Mkdir("dir", 0o755)
	row("Mkdir", err)
	info, err = os.Stat("dir")
	row("Stat dir", fmt.Sprintf("%v name=%s dir=%v mode=%v type=%v", err, info.Name(), info.IsDir(), info.Mode(), info.Mode().Type()))
	err = os.Mkdir("dir", 0o755)
	row("Mkdir existing", err)
	row("Mkdir existing IsExist", os.IsExist(err))
	err = os.Mkdir("no/parent/here", 0o755)
	row("Mkdir without parent", err)
	err = os.MkdirAll("deep/a/b/c", 0o755)
	row("MkdirAll", err)
	err = os.MkdirAll("deep/a/b/c", 0o755)
	row("MkdirAll again", err)
	err = os.MkdirAll("size.bin/x", 0o755)
	row("MkdirAll over a file", err)
	info, err = os.Stat("deep/a/b")
	row("Stat deep", fmt.Sprintf("%v %s %v", err, info.Name(), info.IsDir()))
	info, err = os.Stat("deep/a/b/")
	row("Stat trailing slash", fmt.Sprintf("%v %s", err, info.Name()))
	info, err = os.Stat(".")
	row("Stat dot", fmt.Sprintf("%v %s %v", err, info.Name(), info.IsDir()))
	os.WriteFile("dir/z.txt", []byte("z"), 0o644)
	os.WriteFile("dir/a.txt", []byte("aa"), 0o644)
	os.WriteFile("dir/m.txt", []byte("mmm"), 0o644)
	os.Mkdir("dir/sub", 0o755)
	entries, err := os.ReadDir("dir")
	row("ReadDir err", err)
	for _, e := range entries {
		info, _ := e.Info()
		size := info.Size()
		if e.IsDir() {
			size = -1
		}
		fmt.Printf("ReadDir entry %-6s dir=%-5v type=%-10v size=%d\n", e.Name(), e.IsDir(), e.Type(), size)
	}
	names := []string{}
	for _, e := range entries {
		names = append(names, e.Name())
	}
	row("ReadDir sorted", sort.StringsAreSorted(names))
	_, err = os.ReadDir("missing")
	row("ReadDir missing", err)
	entries, err = os.ReadDir("deep/a/b/c")
	row("ReadDir empty", fmt.Sprint(len(entries), " ", err))
	dirFile, err := os.Open("dir")
	row("Open dir", err)
	info, err = dirFile.Stat()
	row("dir File.Stat", fmt.Sprintf("%v %s %v", err, info.Name(), info.IsDir()))
	buf := make([]byte, 4)
	n, err := dirFile.Read(buf)
	row("dir Read", fmt.Sprint(n, " ", err))
	n, err = dirFile.ReadAt(buf, 0)
	row("dir ReadAt", fmt.Sprint(n, " ", err))
	_, err = dirFile.Write(buf)
	row("dir Write", err)
	// The order of the entries of an open directory is the order of the file
	// system, thus the program sorts the union of the 2 reads.
	first, err := dirFile.ReadDir(1)
	row("dir ReadDir 1", fmt.Sprint(len(first), " ", err))
	list, err := dirFile.Readdirnames(-1)
	list = append(list, first[0].Name())
	sort.Strings(list)
	row("Readdirnames union", fmt.Sprintf("%v %v", list, err))
	list, err = dirFile.Readdirnames(-1)
	row("Readdirnames again", fmt.Sprintf("%v %v", list, err))
	_, err = dirFile.ReadDir(1)
	row("ReadDir 1 at end", err)
	row("dir Close", dirFile.Close())
	dirFile, _ = os.Open("dir")
	infos, err := dirFile.Readdir(-1)
	row("Readdir count", fmt.Sprint(len(infos), " ", err))
	dirFile.Close()
	dirFile, _ = os.OpenFile("dir", os.O_RDONLY, 0)
	list, err = dirFile.Readdirnames(2)
	row("OpenFile dir Readdirnames 2", fmt.Sprint(len(list), " ", err))
	dirFile.Close()
	err = os.Truncate("size.bin", 10)
	row("Truncate", err)
	info, _ = os.Stat("size.bin")
	row("Size after Truncate", info.Size())
	err = os.Truncate("size.bin", 20)
	info, _ = os.Stat("size.bin")
	row("Truncate grows", fmt.Sprint(info.Size(), " ", err))
	data, _ := os.ReadFile("size.bin")
	row("grown bytes are zero", strings.Count(string(data), "\x00"))
	err = os.Truncate("missing.txt", 0)
	row("Truncate missing", err)
	f, _ := os.OpenFile("size.bin", os.O_RDWR, 0o644)
	err = f.Truncate(5)
	f.Close()
	info, _ = os.Stat("size.bin")
	row("File.Truncate", fmt.Sprint(info.Size(), " ", err))
	err = os.Chmod("size.bin", 0o600)
	row("Chmod", err)
	err = os.Chmod("size.bin", 0o644)
	row("Chmod back", err)
	err = os.Chmod("missing.txt", 0o644)
	row("Chmod missing", err)
	for _, m := range []fs.FileMode{0o644, 0o755, 0o600, 0o700, 0o777, 0o400, fs.ModeDir | 0o755, fs.ModeSymlink | 0o777, 0o4755, fs.ModeSetuid | 0o755, fs.ModeSticky | 0o1777} {
		fmt.Printf("FileMode %-14v perm=%v\n", m, m.Perm())
	}
}

func moves() {
	os.WriteFile("from.txt", []byte("moving"), 0o644)
	err := os.Rename("from.txt", "to.txt")
	row("Rename", err)
	_, err = os.Stat("from.txt")
	row("old is gone", os.IsNotExist(err))
	data, err := os.ReadFile("to.txt")
	row("new holds the data", fmt.Sprintf("%q %v", data, err))
	os.WriteFile("other.txt", []byte("other"), 0o644)
	err = os.Rename("to.txt", "other.txt")
	data, _ = os.ReadFile("other.txt")
	row("Rename over a file", fmt.Sprintf("%v %q", err, data))
	err = os.Rename("missing.txt", "x.txt")
	row("Rename missing", err)
	var le *os.LinkError
	row("as LinkError", fmt.Sprintf("%v op=%q old=%q new=%q err=%v", errors.As(err, &le), le.Op, le.Old, le.New, le.Err))
	row("LinkError IsNotExist", os.IsNotExist(err))
	err = os.Remove("other.txt")
	row("Remove", err)
	err = os.Remove("other.txt")
	row("Remove again", err)
	row("Remove again IsNotExist", os.IsNotExist(err))
	err = os.Remove("dir")
	row("Remove full dir", err)
	err = os.Remove("dir/sub")
	row("Remove empty dir", err)
	err = os.RemoveAll("dir")
	row("RemoveAll", err)
	_, err = os.Stat("dir")
	row("RemoveAll removed", os.IsNotExist(err))
	err = os.RemoveAll("dir")
	row("RemoveAll missing", err)
	err = os.RemoveAll("size.bin")
	row("RemoveAll of a file", err)
	err = os.RemoveAll("")
	row("RemoveAll of empty", err)
	os.WriteFile("same.txt", []byte("same"), 0o644)
	err = os.Rename("same.txt", "same.txt")
	row("Rename to itself", err)
	data, _ = os.ReadFile("same.txt")
	row("Rename to itself keeps", fmt.Sprintf("%q", data))
	entries, _ := os.ReadDir(".")
	names := []string{}
	for _, e := range entries {
		names = append(names, e.Name())
	}
	row("the directory at the end", names)
}

func misc() {
	f, err := os.CreateTemp(".", "conf-*.txt")
	row("CreateTemp", err)
	row("CreateTemp name pattern", strings.HasPrefix(f.Name(), "./conf-") && strings.HasSuffix(f.Name(), ".txt"))
	f.Close()
	os.Remove(f.Name())
	sub, err := os.MkdirTemp(".", "sub-")
	row("MkdirTemp", err)
	row("MkdirTemp prefix", strings.HasPrefix(sub, "./sub-"))
	other, _ := os.MkdirTemp(".", "sub-")
	row("MkdirTemp differs", other != sub)
	os.Remove(other)
	info, _ := os.Stat(sub)
	row("MkdirTemp IsDir", info.IsDir())
	os.Remove(sub)
	_, err = os.CreateTemp("missing-dir", "x")
	row("CreateTemp in a missing dir", strings.HasPrefix(err.Error(), "open missing-dir/x"))
	row("IsPathSeparator /", os.IsPathSeparator('/'))
	row("IsPathSeparator a", os.IsPathSeparator('a'))
	row("PathSeparator", string(os.PathSeparator))
	row("PathListSeparator", string(os.PathListSeparator))
	row("DevNull", os.DevNull)
	row("ErrNotExist", os.ErrNotExist)
	row("ErrExist", os.ErrExist)
	row("ErrPermission", os.ErrPermission)
	row("ErrClosed", os.ErrClosed)
	row("ErrInvalid", os.ErrInvalid)
	row("ErrNoDeadline", os.ErrNoDeadline)
	row("ErrDeadlineExceeded", os.ErrDeadlineExceeded)
	row("ModeDir", os.ModeDir)
	row("ModePerm", os.ModePerm)
	row("Args count", len(os.Args))
	os.Setenv("CONF_OS_KEY", "value")
	row("Getenv", os.Getenv("CONF_OS_KEY"))
	v, ok := os.LookupEnv("CONF_OS_KEY")
	row("LookupEnv", fmt.Sprintf("%q %v", v, ok))
	v, ok = os.LookupEnv("CONF_OS_MISSING")
	row("LookupEnv missing", fmt.Sprintf("%q %v", v, ok))
	os.Unsetenv("CONF_OS_KEY")
	_, ok = os.LookupEnv("CONF_OS_KEY")
	row("Unsetenv", ok)
	row("ExpandEnv", os.Expand("$A and ${B}x and $$ and ${", func(k string) string { return "<" + k + ">" }))
	row("Getpid > 0", os.Getpid() > 0)
	wd, err := os.Getwd()
	row("Getwd", fmt.Sprint(wd != "", " ", err))
	info, err = os.Stat(wd)
	row("Getwd is a dir", fmt.Sprint(info.IsDir(), " ", err))
	var w io.Writer = os.Stdout
	fmt.Fprintln(w, "Stdout as io.Writer            ok")
	os.Stdout.WriteString("Stdout WriteString             ok\n")
	os.Stdout.Write([]byte("Stdout Write                   ok\n"))
	row("Stdout Name", os.Stdout.Name())
	row("Stdin Name", os.Stdin.Name())
	row("Stderr Name", os.Stderr.Name())
	fsys := os.DirFS(".")
	data, err := fs.ReadFile(fsys, "a.txt")
	row("DirFS ReadFile", fmt.Sprintf("%d %v", len(data), err))
	_, err = fs.ReadFile(fsys, "missing.txt")
	row("DirFS missing", err)
	entries, err := fs.ReadDir(fsys, ".")
	row("DirFS ReadDir count", fmt.Sprint(len(entries), " ", err))
	_, err = fs.ReadFile(fsys, "../x")
	row("DirFS escape", err)
	matches, err := fs.Glob(fsys, "*.txt")
	row("DirFS Glob", fmt.Sprintf("%v %v", matches, err))
	err = fs.WalkDir(fsys, ".", func(path string, d fs.DirEntry, err error) error {
		if d.IsDir() && path != "." {
			return fs.SkipDir
		}
		return err
	})
	row("DirFS WalkDir", err)
}

// nilFile proves that each method of a nil *os.File gives ErrInvalid, and that
// Name reads the field with no test, exactly as Go does.
func nilFile() {
	var f *os.File
	n, err := f.Write([]byte("x"))
	row("nil write", fmt.Sprint(n, " ", err, " ", errors.Is(err, os.ErrInvalid)))
	n, err = f.Read(make([]byte, 1))
	row("nil read", fmt.Sprint(n, " ", err))
	row("nil close", fmt.Sprint(f.Close()))
	_, err = f.Seek(0, io.SeekStart)
	row("nil seek", fmt.Sprint(err))
	_, err = f.Stat()
	row("nil stat", fmt.Sprint(err))
	_, err = f.ReadDir(1)
	row("nil readdir", fmt.Sprint(err))
	row("nil sync", fmt.Sprint(f.Sync()))
	_, err = f.WriteString("y")
	row("nil writestring", fmt.Sprint(err))
	_, err = f.ReadAt(make([]byte, 1), 0)
	row("nil readat", fmt.Sprint(err))
	_, err = f.WriteAt([]byte("y"), 0)
	row("nil writeat", fmt.Sprint(err))
}

func main() {
	nilFile()
	dir, err := os.MkdirTemp("", "confos-")
	if err != nil {
		fmt.Println("MkdirTemp failed:", err)
		return
	}
	defer os.RemoveAll(dir)
	if err := os.Chdir(dir); err != nil {
		fmt.Println("Chdir failed:", err)
		return
	}
	fmt.Println("== the files ==")
	files()
	fmt.Println("== the flags ==")
	flags()
	fmt.Println("== Stat and the directories ==")
	stats()
	fmt.Println("== Rename and Remove ==")
	moves()
	fmt.Println("== the rest ==")
	misc()
}
